int wmain(int argc,wchar_t **argv){if(argc!=3)return 2;int remove=wcscmp(argv[1],L"remove")==0;if(!remove&&wcscmp(argv[1],L"add")!=0)return 2;const wchar_t *dir=argv[2];if(!*dir||wcschr(dir,L';'))return 2;HKEY key;DWORD disposition;if(RegCreateKeyExW(HKEY_CURRENT_USER,L"Environment",0,NULL,0,KEY_QUERY_VALUE|KEY_SET_VALUE,NULL,&key,&disposition)!=ERROR_SUCCESS)return 3;DWORD type=REG_EXPAND_SZ,bytes=0;LONG status=RegQueryValueExW(key,L"Path",NULL,&type,NULL,&bytes);if(status!=ERROR_SUCCESS&&status!=ERROR_FILE_NOT_FOUND){RegCloseKey(key);return 3;}if(status==ERROR_FILE_NOT_FOUND){type=REG_EXPAND_SZ;bytes=0;}if((type!=REG_SZ&&type!=REG_EXPAND_SZ)||bytes>65536){RegCloseKey(key);return 4;}wchar_t *old=calloc(bytes+2,sizeof(wchar_t));if(!old){RegCloseKey(key);return 4;}if(bytes&&RegQueryValueExW(key,L"Path",NULL,&type,(BYTE*)old,&bytes)!=ERROR_SUCCESS){free(old);RegCloseKey(key);return 3;}size_t cap=wcslen(old)+wcslen(dir)+4;wchar_t *result=calloc(cap,sizeof(wchar_t));if(!result){free(old);RegCloseKey(key);return 4;}int found=0;const wchar_t *p=old;size_t n=0;while(*p){const wchar_t *end=wcschr(p,L';');if(!end)end=p+wcslen(p);size_t len=end-p;int same=len==wcslen(dir)&&_wcsnicmp(p,dir,len)==0;if(same)found=1;if(!(remove&&same)){if(n)result[n++]=L';';wmemcpy(result+n,p,len);n+=len;}p=*end?end+1:end;}if((!remove&&found)||(remove&&!found)){free(old);free(result);RegCloseKey(key);return 10;}if(!remove){wcscpy(result,old);n=wcslen(result);if(n&&result[n-1]!=L';')result[n++]=L';';wcscpy(result+n,dir);}else result[n]=0;if(wcslen(result)>32760){free(old);free(result);RegCloseKey(key);return 4;}status=RegSetValueExW(key,L"Path",0,type,(BYTE*)result,(DWORD)((wcslen(result)+1)*sizeof(wchar_t)));free(old);free(result);RegCloseKey(key);DWORD_PTR ignored;SendMessageTimeoutW(HWND_BROADCAST,WM_SETTINGCHANGE,0,(LPARAM)L"Environment",SMTO_ABORTIFHUNG,1000,&ignored);return status==ERROR_SUCCESS?0:3;}
